import{_ as t,c as s,o,a2 as r}from"./chunks/framework.jqDK1qTK.js";const u=JSON.parse('{"title":"Proposals","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/_index.md","to":"README.md"},"title":"Proposals","weight":34,"prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/_index.md","filePath":"docs/proposals/_index.md","lastUpdated":null}'),a={name:"docs/proposals/_index.md"};function i(n,e,l,h,c,d){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="gardener-enhancement-proposals-geps" tabindex="-1">Gardener Enhancement Proposals (GEPs) <a class="header-anchor" href="#gardener-enhancement-proposals-geps" aria-label="Permalink to &quot;Gardener Enhancement Proposals (GEPs)&quot;">​</a></h1><p>A <strong>Gardener Enhancement Proposal (GEP)</strong> is the primary mechanism to propose, communicate, and coordinate <strong>project-wide changes</strong> for the Gardener project.</p><p>GEPs are used for topics that require discussion and decision-making in Gardener&#39;s <strong>Product Steering Committee (PSC)</strong> and/or <strong>Technical Steering Committee (TSC)</strong>.</p><hr><h2 id="🚀-quick-start-for-the-gep-process" tabindex="-1">🚀 Quick Start for the GEP Process <a class="header-anchor" href="#🚀-quick-start-for-the-gep-process" aria-label="Permalink to &quot;🚀 Quick Start for the GEP Process&quot;">​</a></h2><ol><li><p><strong>Socialize the idea early</strong></p><ul><li>Discuss your idea with the Gardener community or relevant stakeholders.</li><li>Suitable forums include: <ul><li>Gardener Slack channels</li><li>Direct discussions with community members</li><li>Direct discussions with PSC/TSC members</li></ul></li><li>The goal is to validate that the topic is worth pursuing and that there is sufficient interest to move forward.</li></ul></li><li><p><strong>Create a GEP</strong></p><ul><li>Follow the <a href="https://github.com/gardener/enhancements/blob/main/README.md#-how-to-propose-a-gardener-enhancement" target="_blank" rel="noreferrer">process</a> and structure outlined in the <a href="https://github.com/gardener/enhancements/blob/main/geps/NNNN-gep-template/README.md" target="_blank" rel="noreferrer"><strong>GEP template</strong></a>.</li><li>Submit the proposal as a Pull Request to this repository.</li><li>A PSC or TSC member will coordinate review and scheduling for the relevant steering meeting.</li></ul></li></ol><hr><h2 id="❓-faqs" tabindex="-1">❓ FAQs <a class="header-anchor" href="#❓-faqs" aria-label="Permalink to &quot;❓ FAQs&quot;">​</a></h2><h3 id="do-i-have-to-use-the-gep-process" tabindex="-1">Do I have to use the GEP process? <a class="header-anchor" href="#do-i-have-to-use-the-gep-process" aria-label="Permalink to &quot;Do I have to use the GEP process?&quot;">​</a></h3><p>In most cases, <strong>yes</strong>.</p><p>GEPs are required for <strong>non-trivial, project-wide changes</strong>, in particular for:</p><ul><li>Proposals that may be <strong>controversial</strong></li><li><strong>New features</strong> beyond very small, incremental additions</li><li><strong>Major changes</strong> to existing functionality</li><li>Topics with <strong>cross-team or ecosystem-wide impact</strong></li><li><strong>New extensions</strong> in the Gardener organizatino</li><li>Changes requiring <strong>PSC or TSC discussion</strong></li></ul><p>The goal is to keep the process lightweight enough that using a GEP is the <strong>default</strong> for significant changes.</p><hr><h3 id="why-should-i-use-the-gep-process" tabindex="-1">Why should I use the GEP process? <a class="header-anchor" href="#why-should-i-use-the-gep-process" aria-label="Permalink to &quot;Why should I use the GEP process?&quot;">​</a></h3><p>The GEP process exists to provide <strong>clarity, transparency, and alignment</strong> across the Gardener project.</p><p>Benefits include:</p><ul><li>A <strong>single, discoverable place</strong> for major proposals and decisions</li><li>Clear articulation of <strong>motivation, scope, and intent</strong></li><li>A structured process with <strong>explicit reviewers and decision-makers</strong></li><li>A durable, searchable <strong>record of decisions and rationale</strong></li><li>Early feedback that often prevents costly redesigns later</li></ul><p>The process is inspired by established proposal systems such as IETF RFCs, Python PEPs, Rust RFCs, and Kubernetes GEPs, but adapted to Gardener&#39;s governance model.</p><hr><h3 id="how-do-psc-and-tsc-fit-into-the-gep-process" tabindex="-1">How do PSC and TSC fit into the GEP process? <a class="header-anchor" href="#how-do-psc-and-tsc-fit-into-the-gep-process" aria-label="Permalink to &quot;How do PSC and TSC fit into the GEP process?&quot;">​</a></h3><p>Gardener has <strong>no SIG-based ownership model</strong>.</p><p>Instead:</p><ul><li><p><strong>Product Steering Committee (PSC)</strong> Evaluates proposals at an <strong>early stage</strong>, focusing on:</p><ul><li>Vision and strategy</li><li>Prioritization and roadmap fit</li><li>The <strong>&quot;Whether / Why&quot;</strong> question</li></ul></li><li><p><strong>Technical Steering Committee (TSC)</strong> Evaluates proposals at a <strong>later stage</strong>, focusing on:</p><ul><li>Architecture and technical direction</li><li>APIs, interfaces, and design choices</li><li>The <strong>&quot;How&quot;</strong> question</li></ul></li></ul><p>A topic typically goes to:</p><ul><li><strong>PSC first</strong>, and</li><li><strong>TSC later</strong>, once a concrete technical design exists.</li></ul><hr><h3 id="where-do-geps-live" tabindex="-1">Where do GEPs live? <a class="header-anchor" href="#where-do-geps-live" aria-label="Permalink to &quot;Where do GEPs live?&quot;">​</a></h3><p>All <strong>project-wide GEPs</strong> live in this repository.</p><p>There are <strong>no SIG subdirectories</strong>.<br> Instead, GEPs are organized by steering context (e.g., Product vs. Technical).</p><p>Subproject-internal proposals <strong>do not belong here</strong> unless they meet the criteria for PSC or TSC discussion.</p><hr><h3 id="when-should-i-not-use-a-gep" tabindex="-1">When should I <em>not</em> use a GEP? <a class="header-anchor" href="#when-should-i-not-use-a-gep" aria-label="Permalink to &quot;When should I *not* use a GEP?&quot;">​</a></h3><p>You usually <strong>do not</strong> need a GEP for:</p><ul><li>Small, isolated bug fixes</li><li>Minor, non-controversial enhancements</li><li>Changes scoped strictly to a single subproject that do <strong>not</strong> meet steering criteria</li></ul><p>When in doubt, err on the side of creating a GEP or ask a PSC/TSC member for guidance.</p><hr><h3 id="how-mature-is-the-gep-process" tabindex="-1">How mature is the GEP process? <a class="header-anchor" href="#how-mature-is-the-gep-process" aria-label="Permalink to &quot;How mature is the GEP process?&quot;">​</a></h3><p>The GEP process is intentionally <strong>evolving</strong>.</p><p>Indicators of a healthy process include:</p><ul><li>A growing set of well-structured GEPs</li><li>Timely steering discussions and documented decisions</li><li>Public, searchable proposals and outcomes</li></ul><p>Improvements to the process are welcome and can be proposed via Pull Requests to this repository.</p><hr><h3 id="what-is-the-naming-convention-for-geps" tabindex="-1">What is the naming convention for GEPs? <a class="header-anchor" href="#what-is-the-naming-convention-for-geps" aria-label="Permalink to &quot;What is the naming convention for GEPs?&quot;">​</a></h3><p>GEPs are now prefixed with their associated tracking issue number. This gives both the GEP a unique identifier and provides an easy breadcrumb for people to find the issue where the current state of the GEP is being updated.</p><h3 id="my-faq-isn-t-answered-here" tabindex="-1">My FAQ isn&#39;t answered here! <a class="header-anchor" href="#my-faq-isn-t-answered-here" aria-label="Permalink to &quot;My FAQ isn&#39;t answered here!&quot;">​</a></h3><p>The GEP process is still evolving! If something is missing or not answered here feel free to reach out to the steering committee members. If you want to propose a change to the GEP process you can open a PR with your proposal.</p>',47)]))}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
